{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Cabozantinib, a dimethoxyaryl amide/ether with activity in brain metastases, showed negligible brain uptake in mice, indicating that a dimethoxyaromatic amide scaffold does not guarantee CNS access; the query's additional polar guanidine and naphthyridine groups likely worsen permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Apremilast, which shares a dimethoxyphenyl amide motif, had a brain/plasma concentration ratio of ≤0.1 in vivo, demonstrating poor brain penetrance despite moderate lipophilicity; this supports a fail prediction for the related query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A methoxybenzamide PET ligand with cyanopyridine/piperazine features showed increased brain uptake after cyclosporin A pretreatment, identifying efflux-transport liability; the query contains analogous methoxyaryl amide and cyano/heteroaromatic features, supporting risk of inadequate CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "CUDC-101, a dimethoxyaryl hydroxamate HDAC inhibitor, showed poor brain accumulation due to inability to cross the BBB; the query's multiple H-bond donors (amide and guanidine NHs) and polar naphthyridine similarly raise the BBB barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "DA-5018, a dimethoxyphenylacetamide capsaicinoid, crossed the BBB with T/P ratios greater than unity in rats; this is the closest permeable analogue and shows the dimethoxyphenylacetamide core is not intrinsically impermeable, but the query's much larger polar guanidine-naphthyridine substituent reduces transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Capsaicin readily crosses the BBB after systemic administration, but it is a small lipophilic vanillylamide without the query's polar guanidine and naphthyridine; this supports permeability of simple aryl amides but is outweighed by the query's additional polar/HBD load.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: although the closest permeable analogues share the dimethoxyphenylacetamide core, the query's N-cyano guanidine and naphthyridine introduce multiple H-bond donors/acceptors and likely efflux liability; several structurally related dimethoxyaryl amides show poor brain penetration, outweighing the capsaicinoid permeability signal.",
  "evidence_gaps": [
    "No direct BBB/PK data for the query or very close analogues.",
    "Morgan similarities to evidence molecules are low (~0.25), limiting transfer strength.",
    "Efflux-transporter status and unbound brain/CSF concentrations for the query are unknown.",
    "Possible active uptake or prodrug behavior was not assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

